"""Static workbenches and task references for three local developer conversions."""
import html

NEW_TOOLS = [
    ('hex-to-rgb','HEX to RGB','CSS & layout','Convert HEX colors to RGB or RGBA. Preview transparency and copy CSS color values.','palette'),
    ('json-unescape','JSON unescape / escape','Encoding','Decode escaped JSON strings or escape plain text. Quotes, newlines and Unicode, one layer at a time.','code'),
    ('hex-to-text','HEX to text','Encoding','Decode HEX bytes as UTF-8 text or encode text as hex. Inspect and download the original bytes.','code'),
]


def new_tool_pages(tool_head, segmented, copy, docs, extra_section, ad_slot, related):
    color = tool_head('hex-to-rgb','CSS & COLOR','HEX to RGB converter','Convert a HEX color to RGB or RGBA, inspect its channels and preview transparency. Switch to RGB input for the reverse conversion.')
    color += '<section class="workbench"><div class="bench-toolbar">'+segmented([('hex','HEX input'),('rgb','RGB input')],'color-modes')+'<span class="quiet">sRGB colors</span></div>'
    color += '''<div class="bench-body"><div class="input-panel"><div id="color-hex-fields"><label for="color-input">HEX color</label><input id="color-input" class="mono" value="#244cda" spellcheck="false" autocomplete="off"><p class="hint">3, 4, 6 or 8 hex digits, with or without #. Alpha comes last.</p></div><div id="color-rgb-fields" hidden><div class="color-channel-inputs"><div><label for="color-r">Red</label><input id="color-r" type="number" min="0" max="255" step="1" value="36"></div><div><label for="color-g">Green</label><input id="color-g" type="number" min="0" max="255" step="1" value="76"></div><div><label for="color-b">Blue</label><input id="color-b" type="number" min="0" max="255" step="1" value="218"></div></div><label for="color-a">Alpha (optional)</label><input id="color-a" type="number" min="0" max="1" step="any" placeholder="Empty means opaque"><p class="hint">Channels: whole numbers from 0 to 255. Alpha: 0 to 1. HEX alpha is rounded to the nearest 8-bit value.</p></div><div class="actions"><button class="button ghost" id="color-clear">Clear</button></div><p class="mono-label example-label">TRY A COMPLETE EXAMPLE</p><div class="example-buttons"><button class="button small" data-color-example="#244cda">Brand blue</button><button class="button small" data-color-example="#abc">Short HEX</button><button class="button small" data-color-example="#33669980">With alpha</button></div><p class="error" id="color-error" role="alert" hidden></p></div><div class="result-panel"><div class="color-swatch" role="img" aria-label="Preview of the converted color over a checkerboard"><div id="color-fill" style="background-color:#244cda"></div></div><div class="result-head"><label class="mono-label" for="color-rgb-output">RGB / RGBA</label>'''+copy('color-rgb-output')+'''</div><textarea id="color-rgb-output" class="mono" rows="2" readonly>rgb(36, 76, 218)</textarea><div class="result-head"><label class="mono-label" for="color-hex-output">NORMALIZED HEX</label>'''+copy('color-hex-output')+'''</div><input id="color-hex-output" class="mono" value="#244CDA" readonly><dl class="color-channel-values"><div><dt>R</dt><dd id="color-red-value">36</dd></div><div><dt>G</dt><dd id="color-green-value">76</dd></div><div><dt>B</dt><dd id="color-blue-value">218</dd></div><div><dt>Alpha byte</dt><dd id="color-alpha-value">255/255</dd></div></dl><p class="result-sub" id="color-note" role="status">Opaque RGB color.</p></div></div></section>'''
    color += ad_slot('tool_primary') + docs('How to convert HEX to RGB','Each pair of HEX digits represents one red, green or blue channel. Enter a color above to see its decimal channel values. A fourth channel controls opacity.','HEX pairs → decimal channels from 0 to 255',[
        ('Can I use a 3-digit HEX color?','Yes. Each digit is repeated: #abc expands to #aabbcc, so its RGB values are 170, 187 and 204.'),
        ('What do the last two digits mean?','In an 8-digit CSS HEX color, the last pair is alpha. 00 is fully transparent and FF is fully opaque. #33669980 has alpha 128/255, approximately 0.501961.'),
        ('Why did my alpha value change slightly?','HEX alpha has 256 possible values. An RGB input alpha of 0.5 rounds to the byte 128, or 128/255. The preview and RGB output use that rounded value to match the generated HEX. To keep an independently chosen opacity in an RGBA result, use <a href="/hex-to-rgba/">HEX to RGBA</a>.'),
        ('How many RGB colors are there?','With 8 bits for each red, green and blue channel, there are 256 × 256 × 256 = 16,777,216 opaque RGB combinations. Alpha adds opacity values; it is separate from those three channels.'),
        ('Does this support every CSS color syntax?','This tool accepts HEX or separate numeric sRGB channels. Named colors, HSL, display-p3 and other CSS color spaces are outside this input format.'),
    ],'<a href="https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Values/hex-color">MDN: CSS HEX colors and alpha</a>')
    color += extra_section('color-reference','Short HEX, full HEX and alpha','These complete examples show the relationship between input notation and channel values.',
        '<div class="table-wrap"><table><thead><tr><th>HEX input</th><th>Channels</th><th>Meaning</th></tr></thead><tbody><tr><td>#244cda</td><td>36, 76, 218</td><td>Opaque RGB</td></tr><tr><td>#abc</td><td>170, 187, 204</td><td>Short notation repeats each digit</td></tr><tr><td>#0f08</td><td>0, 255, 0; alpha 136/255</td><td>Four-digit short notation includes alpha</td></tr><tr><td>#33669980</td><td>51, 102, 153; alpha 128/255</td><td>Eight-digit notation includes alpha</td></tr></tbody></table></div><p>Alpha text is rounded to six decimal places; the byte fraction remains visible. This converter does not measure color contrast or guarantee accessible color combinations. To add opacity directly to a 6-digit color, use the <a href="/hex-to-rgba/">HEX to RGBA converter</a>. For layout units, use <a href="/px-to-rem/">PX to REM</a>, <a href="/rem-to-px/">REM to PX</a> or the <a href="/guides/rem-vs-em/">CSS unit guide</a>.</p>')
    color += ad_slot('tool_secondary') + related('hex-to-rgb')

    js = tool_head('json-unescape','ENCODING','JSON unescape & escape','Read escaped JSON strings or turn plain text into a JSON string. Handle quotes, backslashes, newlines and Unicode one layer at a time, in your browser.')
    js += '<section class="workbench"><div class="bench-toolbar">'+segmented([('unescape','Unescape'),('escape','Escape')],'json-modes')+'<span class="quiet">One layer per conversion</span></div><div class="bench-body"><div class="input-panel">'
    js += '''<div id="json-kind-wrap"><label for="json-input-kind">Input format</label><select id="json-input-kind"><option value="literal">Complete string (with quotes)</option><option value="content">String content (without quotes)</option></select></div><div class="check-field" id="json-wrap-field" hidden><label><input id="json-wrap" type="checkbox" checked> Include outer double quotes</label></div><label for="json-input" id="json-input-label">Escaped JSON string</label><textarea id="json-input" class="mono" rows="8" spellcheck="false">'''+html.escape(r'"Hello\nworld\u0021"')+'''</textarea><p class="hint">Choose whether your input includes its outer quotes. Up to 1 million UTF-16 code units. Input is treated as text.</p><div class="actions"><button class="button primary" id="json-convert">Unescape one layer</button><button class="button ghost" id="json-clear">Clear</button></div><div class="example-buttons"><button class="button small" data-json-example="unicode">Unicode text</button><button class="button small" data-json-example="content">Escaped content</button><button class="button small" data-json-example="double">Two layers</button><button class="button small" data-json-example="empty">Empty string</button></div><p class="error" id="json-error" role="alert" hidden></p></div><div class="result-panel"><div class="result-head"><label class="mono-label" id="json-output-label" for="json-output">UNESCAPED TEXT</label>'''+copy('json-copy')+'''</div><textarea class="mono result-editor" id="json-output" rows="11" readonly>Hello
world!</textarea><span id="json-copy" hidden></span><p class="result-sub" id="json-stats" role="status"></p><div class="actions"><button class="button" id="json-download" disabled>Download result</button><button class="button" id="json-next-layer" hidden>Unescape result once more</button></div><p class="hint">Unescaping one string does not execute its contents or format a whole JSON document.</p></div></div></section>'''
    js += ad_slot('tool_primary') + docs('How to unescape a JSON string','Select Complete JSON string when the input includes outer double quotes. Select Escaped string content when you have only the contents between those quotes. The result is plain text; braces in that text do not change its type.','Escaped JSON string → one decoded text layer',[
        ('How do I escape double quotes in JSON?','Use Escape mode with your original plain text. A quote becomes \\&quot; inside the encoded string, and a backslash becomes \\\\. Leave Include outer double quotes selected when the destination expects a complete JSON string.'),
        ('Why are backslashes still visible?','The original value may contain more than one layer of string encoding, or its actual text may contain backslashes. Each conversion removes one layer. The extra button appears only when the result is itself a complete JSON string. See the <a href="/guides/json-double-encoding/">JSON backslashes and double-encoding guide</a> for a complete type-by-type example.'),
        ('Does this format an entire JSON object?','No. Unescape expects a JSON string or escaped string contents. Objects, arrays, numbers, booleans and null are different JSON values and are rejected in Complete JSON string mode.'),
        ('Can I convert an empty string?','Yes. In Unescape mode, use the complete input "" or the Empty string example. In Escape mode, clear the input and select Escape text to produce "". An empty decoded result can be downloaded as a zero-byte text file.'),
        ('Why is a Unicode escape rejected?','Malformed escape sequences are rejected. This tool also requires well-formed Unicode text, so a decoded unpaired UTF-16 surrogate is rejected even though JSON parsers can represent such a code unit.'),
    ],'<a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/JSON/parse">MDN: JSON.parse and JSON grammar</a> · <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/JSON/stringify">MDN: JSON.stringify</a>')
    js += extra_section('json-string-reference','Quotes, newlines and nested strings','Use a complete example and choose its input format deliberately.',r'''<div class="table-wrap"><table><thead><tr><th>Input</th><th>Input format</th><th>Result</th></tr></thead><tbody><tr><td><code>&quot;Hello\nworld&quot;</code></td><td>Complete JSON string</td><td>Two lines of text</td></tr><tr><td><code>Hello\nworld</code></td><td>Escaped string content</td><td>The same two lines</td></tr><tr><td><code>&quot;\u4e2d\u6587&quot;</code></td><td>Complete JSON string</td><td>中文</td></tr><tr><td><code>{&quot;ok&quot;:true}</code></td><td>Complete JSON string</td><td>Rejected: this is an object, not a string</td></tr></tbody></table></div><p>Escaping turns text into a representation that can fit inside a JSON string. It does not encrypt it. This is a different operation from URL decoding, HTML entity decoding or <a href="/base64/">Base64 decoding</a>. For alphabet and byte issues, see the <a href="/guides/fix-invalid-base64/">Base64 troubleshooting guide</a>. For full documents, use <a href="/yaml-to-json/">YAML ↔ JSON</a> or <a href="/csv-to-json/">CSV ↔ JSON</a>. Inspect a complete example in <a href="/guides/json-double-encoding/">the JSON encoding-layer guide</a> before changing a producer or deleting backslashes. Inputs are held in memory and are not put into URLs or sent to a conversion service.</p>''')
    js += ad_slot('tool_secondary') + related('json-unescape')

    hx = tool_head('hex-to-text','ENCODING & BYTES','HEX to text decoder','Decode hexadecimal bytes to UTF-8 text, or encode text as HEX. Inspect the original bytes even when they are not valid UTF-8.')
    hx += '<section class="workbench"><div class="bench-toolbar">'+segmented([('decode','HEX to text'),('encode','Text to HEX')],'hex-modes')+'<span class="quiet">UTF-8 text & original bytes</span></div><div class="bench-body"><div class="input-panel">'
    hx += '''<label for="hex-input" id="hex-input-label">HEX bytes</label><textarea id="hex-input" class="mono" rows="8" spellcheck="false">48 65 6c 6c 6f</textarea><p class="hint" id="hex-input-hint">Complete byte groups, optionally prefixed with 0x, separated by whitespace.</p><div class="actions"><button class="button primary" id="hex-convert">Decode HEX</button><button class="button ghost" id="hex-clear">Clear</button></div><div class="example-buttons"><button class="button small" data-hex-example="hello">Hello</button><button class="button small" data-hex-example="unicode">Unicode</button><button class="button small" data-hex-example="prefix">0x prefixes</button><button class="button small" data-hex-example="binary">Binary bytes</button></div><div class="hex-output-options"><label><input type="checkbox" id="hex-spaced" checked> Separate output bytes</label><label><input type="checkbox" id="hex-uppercase"> Uppercase output</label></div><p class="error" id="hex-error" role="alert" hidden></p></div><div class="result-panel"><div id="hex-main-result"><div class="result-head"><label class="mono-label" id="hex-output-label" for="hex-output">DECODED UTF-8 TEXT</label>'''+copy('hex-copy')+'''</div><textarea class="mono result-editor" id="hex-output" rows="7" readonly>Hello</textarea></div><span id="hex-copy" hidden></span><p class="result-sub" id="hex-stats" role="status"></p><p class="byte-note" id="hex-note" role="status" hidden></p><div id="hex-normalized-wrap"><div class="result-head"><label class="mono-label" for="hex-normalized">NORMALIZED HEX BYTES</label>'''+copy('hex-normalized')+'''</div><textarea id="hex-normalized" class="mono" rows="3" readonly>48 65 6c 6c 6f</textarea></div><div class="actions"><button class="button" id="hex-download" disabled>Download text</button><button class="button" id="hex-bytes-download" disabled>Download bytes</button></div></div></div></section>'''
    hx += ad_slot('tool_primary') + docs('How to translate hexadecimal to text','Each pair of HEX digits represents a byte. A text encoding then determines how those bytes become characters. This tool uses strict UTF-8 for text while retaining valid binary bytes separately.','HEX pairs → bytes → strict UTF-8 text',[
        ('Why is my HEX input rejected?','Each whitespace-separated group must contain an even number of hexadecimal digits, optionally after 0x. Characters outside 0–9 and A–F, empty prefixes, commas and incomplete bytes are rejected rather than guessed.'),
        ('Why do valid bytes produce no text?','A valid HEX representation can contain binary data or text in another encoding. For example, fb ff ef is valid HEX but invalid UTF-8. The tool keeps the HEX and original bytes available without inventing replacement text.'),
        ('Is this the same as converting a number?','No. Here 41 is the byte 0x41, which is the character A in UTF-8. Converting the hexadecimal number 41 to decimal would produce the number 65. Those are different tasks.'),
        ('Do Chinese characters and emoji work?','Yes. Text is encoded as UTF-8 bytes before HEX output. Decoding requires valid UTF-8. An initial U+FEFF character is preserved rather than silently removed.'),
        ('What are the size limits?','HEX input is limited to 5,000,000 characters and 1,000,000 decoded bytes. Text input is limited to 250,000 UTF-16 code units. Output formatting uses the same original bytes.'),
    ],'<a href="https://developer.mozilla.org/en-US/docs/Web/API/TextDecoder/fatal">MDN: strict text decoding</a> · <a href="https://developer.mozilla.org/en-US/docs/Web/API/TextEncoder">MDN: UTF-8 encoding</a>')
    hx += extra_section('hex-text-reference','Complete byte examples','Choose the interpretation that matches your source data.',r'''<div class="table-wrap"><table><thead><tr><th>HEX</th><th>UTF-8 result</th></tr></thead><tbody><tr><td>48 65 6c 6c 6f</td><td>Hello</td></tr><tr><td>0x48 0x65 0x6c 0x6c 0x6f</td><td>The same bytes with prefixes</td></tr><tr><td>e4 b8 ad e6 96 87</td><td>中文</td></tr><tr><td>f0 9f 91 8b</td><td>👋</td></tr><tr><td>fb ff ef</td><td>Valid bytes; not UTF-8 text</td></tr><tr><td>4 8</td><td>Rejected: incomplete byte groups</td></tr></tbody></table></div><p>The byte download does not transform or repair data. For example, <code>c3 28</code> is a valid pair of HEX bytes but invalid UTF-8: the byte following C3 is not a continuation byte. Deleting one byte or replacing the error with a guessed character changes the data. Keep the original byte download and check the source encoding. To inspect URL-safe encoded bytes, use the <a href="/base64url-decode/">Base64URL decoder</a>. The <a href="/guides/fix-invalid-base64/">encoding troubleshooting guide</a> explains why a valid encoding does not establish a text or image format.</p>''')
    hx += ad_slot('tool_secondary') + related('hex-to-text')
    note='<noscript><p class="hint">JavaScript enables conversion, copying and downloads. The complete examples and reference sections below remain readable.</p></noscript>'
    return [
        ('hex-to-rgb','HEX to RGB Converter — RGB & RGBA Color Codes','Convert HEX colors to RGB or RGBA in your browser. Preview 3-, 4-, 6- and 8-digit colors, inspect alpha and copy CSS values.',color+note),
        ('json-unescape','JSON Unescape & Escape — Quotes, Unicode and Newlines','Unescape JSON strings or escape plain text. Decode quotes, backslashes, newlines and Unicode one layer at a time with clear validation.',js+note),
        ('hex-to-text','HEX to Text Converter & Decoder — UTF-8','Decode HEX bytes to UTF-8 text or encode text as hexadecimal. Inspect original bytes, handle separators and find invalid characters in your browser.',hx+note),
    ]
